COPY (
  SELECT strftime(month,'%Y-%m') month, SUM(revenue) revenue, SUM(items) items,
    SUM(revenue)-LAG(SUM(revenue)) OVER (ORDER BY month) mom_abs
  FROM '/data/thelook_2023_agg.parquet' GROUP BY month ORDER BY month
) TO '/work/monthly.csv' (HEADER, DELIMITER ',');
SELECT * FROM '/work/monthly.csv';

COPY (
  SELECT category,
    SUM(CASE WHEN month='2023-02-01' THEN revenue END)-SUM(CASE WHEN month='2023-01-01' THEN revenue END) delta
  FROM '/data/thelook_2023_agg.parquet' WHERE month IN (DATE '2023-01-01',DATE '2023-02-01')
  GROUP BY category ORDER BY delta LIMIT 8
) TO '/work/cat_delta.csv' (HEADER, DELIMITER ',');
SELECT * FROM '/work/cat_delta.csv';

SELECT strftime(month,'%Y-%m') month, ROUND(SUM(revenue),0) revenue, SUM(items) items,
  ROUND(SUM(revenue)-LAG(SUM(revenue)) OVER (ORDER BY month),0) mom_abs
FROM '/data/thelook_2023_agg.parquet' GROUP BY month ORDER BY month;

